-- Optimized query with specific columns and indexes
SELECT u.id, u.name, u.email, COUNT(p.id) as post_count
FROM users u 
LEFT JOIN posts p ON u.id = p.user_id AND p.status = 'published'
WHERE u.status = 'active'
GROUP BY u.id, u.name, u.email;

-- Add indexes for performance
CREATE INDEX idx_users_status ON users(status);
CREATE INDEX idx_posts_user_status ON posts(user_id, status);

const redis = require('redis');
const client = redis.createClient();

class CacheService {
  async get(key) {
    try {
      const data = await client.get(key);
      return data ? JSON.parse(data) : null;
    } catch (error) {
      console.error('Cache get error:', error);
      return null;
    }
  }

  async set(key, data, ttl = 300) {
    try {
      await client.setex(key, ttl, JSON.stringify(data));
    } catch (error) {
      console.error('Cache set error:', error);
    }
  }

  async invalidate(pattern) {
    try {
      const keys = await client.keys(pattern);
      if (keys.length > 0) {
        await client.del(keys);
      }
    } catch (error) {
      console.error('Cache invalidation error:', error);
    }
  }
}

// Usage in API endpoint
app.get('/api/users/:id', async (req, res) => {
  const cacheKey = `user:${req.params.id}`;
  let user = await cacheService.get(cacheKey);

  if (!user) {
    user = await database.getUserById(req.params.id);
    await cacheService.set(cacheKey, user, 600); // 10 minutes TTL
  }

  res.json(user);
});

// Route-based code splitting
import { lazy, Suspense } from 'react';
import { Routes, Route } from 'react-router-dom';

const Dashboard = lazy(() => import('./pages/Dashboard'));
const Profile = lazy(() => import('./pages/Profile'));
const Settings = lazy(() => import('./pages/Settings'));

function App() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <Routes>
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/profile" element={<Profile />} />
        <Route path="/settings" element={<Settings />} />
      </Routes>
    </Suspense>
  );
}

// Component lazy loading with intersection observer
const LazyComponent = ({ component: Component, ...props }) => {
  const [isIntersecting, setIsIntersecting] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsIntersecting(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <div ref={ref}>
      {isIntersecting ? <Component {...props} /> : <div>Loading...</div>}
    </div>
  );
};

